using System.Globalization;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using PFA_FVG_Scanner.Domain.Governance;

namespace PFA_FVG_Scanner.Data;

public sealed record GovernanceIncident(string IncidentId,string Severity,string Category,string? AccountId,string? InstanceId,DateTime OccurredAtUtc,string Summary,string EvidenceJson,string ContentHash);
public sealed record GovernanceApprovalRevocation(string ApprovalId,DateTime RevokedAtUtc,string RevokedBy,string Reason);
public sealed record GovernanceSuspensionResume(string SuspensionId,DateTime ResumedAtUtc,string ResumedBy,string Reason);

public sealed class GovernanceRepository
{
    private readonly PfaDatabase _database;public GovernanceRepository(PfaDatabase database)=>_database=database;
    public async Task SavePolicyAsync(GovernancePolicy policy,CancellationToken token=default){if(!policy.IsValid())throw new ArgumentException("Governance policy is invalid.");await InsertImmutableAsync("GovernancePolicies","PolicyId=$id AND PolicyVersion=$version",policy.ContentHash(),JsonSerializer.Serialize(policy),"""
        INSERT INTO GovernancePolicies(PolicyId,PolicyVersion,EffectiveFromUtc,EffectiveToUtc,ContentHash,PolicyJson,CreatedAtUtc)
        VALUES($id,$version,$effective,$expires,$hash,$json,$created)
        """,[("$id",policy.PolicyId),("$version",policy.PolicyVersion),("$effective",policy.EffectiveFromUtc.ToString("O")),("$expires",policy.EffectiveToUtc?.ToString("O")),("$created",policy.CreatedAtUtc.ToString("O"))],token);}
    public async Task<GovernancePolicy?> GetEffectivePolicyAsync(DateTime nowUtc,CancellationToken token=default)
    {await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="SELECT PolicyJson FROM GovernancePolicies WHERE EffectiveFromUtc<=$now AND (EffectiveToUtc IS NULL OR EffectiveToUtc>=$now) ORDER BY EffectiveFromUtc DESC,rowid DESC LIMIT 1";Add(command,"$now",nowUtc.ToUniversalTime().ToString("O"));var scalar=await command.ExecuteScalarAsync(token);return Deserialize<GovernancePolicy>(scalar);}
    public Task GrantApprovalAsync(GovernanceApproval approval,CancellationToken token=default)=>AppendEventAsync("GovernanceApprovalEvents",approval.ApprovalId,"Granted",approval.GrantedAtUtc,approval.GrantedBy,approval.Reason,approval,token);
    public Task RevokeApprovalAsync(GovernanceApprovalRevocation revocation,CancellationToken token=default)=>AppendEventAsync("GovernanceApprovalEvents",revocation.ApprovalId,"Revoked",revocation.RevokedAtUtc,revocation.RevokedBy,revocation.Reason,revocation,token);
    public async Task<IReadOnlyList<GovernanceApproval>> GetApprovalsAsync(CancellationToken token=default)
    {var rows=await ReadEventsAsync("GovernanceApprovalEvents","ApprovalId",token);var output=new List<GovernanceApproval>();foreach(var group in rows.GroupBy(x=>x.SubjectId)){var grant=group.FirstOrDefault(x=>x.Type=="Granted");if(string.IsNullOrEmpty(grant.SubjectId))continue;var value=JsonSerializer.Deserialize<GovernanceApproval>(grant.Json)!;var revoke=group.LastOrDefault(x=>x.Type=="Revoked");if(!string.IsNullOrEmpty(revoke.SubjectId)){var r=JsonSerializer.Deserialize<GovernanceApprovalRevocation>(revoke.Json)!;value=value with{Revoked=true,RevokedAtUtc=r.RevokedAtUtc,RevokedBy=r.RevokedBy,RevocationReason=r.Reason};}output.Add(value);}return output;}
    public Task SuspendAsync(GovernanceSuspension value,CancellationToken token=default)=>AppendEventAsync("GovernanceSuspensionEvents",value.SuspensionId,"Suspended",value.SuspendedAtUtc,value.Actor,value.Reason,value,token);
    public Task ResumeAsync(GovernanceSuspensionResume value,CancellationToken token=default)=>AppendEventAsync("GovernanceSuspensionEvents",value.SuspensionId,"Resumed",value.ResumedAtUtc,value.ResumedBy,value.Reason,value,token);
    public async Task<IReadOnlyList<GovernanceSuspension>> GetSuspensionsAsync(CancellationToken token=default)
    {var rows=await ReadEventsAsync("GovernanceSuspensionEvents","SuspensionId",token);var output=new List<GovernanceSuspension>();foreach(var group in rows.GroupBy(x=>x.SubjectId)){var created=group.FirstOrDefault(x=>x.Type=="Suspended");if(string.IsNullOrEmpty(created.SubjectId))continue;var value=JsonSerializer.Deserialize<GovernanceSuspension>(created.Json)!;var resume=group.LastOrDefault(x=>x.Type=="Resumed");if(!string.IsNullOrEmpty(resume.SubjectId)){var r=JsonSerializer.Deserialize<GovernanceSuspensionResume>(resume.Json)!;value=value with{IsActive=false,ResumedAtUtc=r.ResumedAtUtc,ResumedBy=r.ResumedBy,ResumeReason=r.Reason};}output.Add(value);}return output;}
    public async Task SaveEmergencyStopAsync(GovernanceEmergencyStop value,CancellationToken token=default){var json=JsonSerializer.Serialize(value);var hash=GovernanceHash.Of(json);await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="INSERT OR IGNORE INTO GovernanceEmergencyStopEvents(EmergencyStopId,IsActive,Reason,Actor,OccurredAtUtc,PayloadJson,ContentHash) VALUES($id,$active,$reason,$actor,$occurred,$json,$hash)";Add(command,"$id",value.EmergencyStopId);Add(command,"$active",value.IsActive?1:0);Add(command,"$reason",value.Reason);Add(command,"$actor",value.Actor);Add(command,"$occurred",value.OccurredAtUtc.ToString("O"));Add(command,"$json",json);Add(command,"$hash",hash);await command.ExecuteNonQueryAsync(token);}
    public async Task<GovernanceEmergencyStop?> GetEmergencyStopAsync(CancellationToken token=default){await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="SELECT PayloadJson FROM GovernanceEmergencyStopEvents ORDER BY OccurredAtUtc DESC,rowid DESC LIMIT 1";return Deserialize<GovernanceEmergencyStop>(await command.ExecuteScalarAsync(token));}
    public async Task SaveDecisionAsync(GovernanceDecision decision,CancellationToken token=default){if(decision.CanRouteToRealBroker)throw new UnauthorizedAccessException("Governance cannot authorize a real broker in Phase 19.");await InsertImmutableAsync("GovernanceDecisions","DecisionId=$id",decision.ContentHash,JsonSerializer.Serialize(decision),"""
        INSERT INTO GovernanceDecisions(DecisionId,RequestId,Outcome,PolicyId,PolicyVersion,AccountId,InstanceId,SignalId,DecidedAtUtc,ContentHash,DecisionJson,CanRouteToRealBroker)
        VALUES($id,$request,$outcome,$policy,$version,$account,$instance,$signal,$decided,$hash,$json,0)
        """,[("$id",decision.DecisionId),("$request",decision.RequestId),("$outcome",decision.Outcome.ToString()),("$policy",decision.PolicyId),("$version",decision.PolicyVersion),("$account",decision.AccountId),("$instance",decision.InstanceId),("$signal",decision.SignalId),("$decided",decision.DecidedAtUtc.ToString("O"))],token);}
    public async Task<IReadOnlyList<GovernanceDecision>> GetDecisionsAsync(string accountId,int limit=100,CancellationToken token=default)
    {var list=new List<GovernanceDecision>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="SELECT DecisionJson FROM GovernanceDecisions WHERE AccountId=$account ORDER BY DecidedAtUtc DESC,rowid DESC LIMIT $limit";Add(command,"$account",accountId);Add(command,"$limit",Math.Clamp(limit,1,500));await using var reader=await command.ExecuteReaderAsync(token);while(await reader.ReadAsync(token))list.Add(JsonSerializer.Deserialize<GovernanceDecision>(reader.GetString(0))!);return list;}
    public async Task SaveIncidentAsync(GovernanceIncident incident,CancellationToken token=default){await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="INSERT OR IGNORE INTO GovernanceIncidents(IncidentId,Severity,Category,AccountId,InstanceId,OccurredAtUtc,Summary,EvidenceJson,ContentHash) VALUES($id,$severity,$category,$account,$instance,$occurred,$summary,$evidence,$hash)";Add(command,"$id",incident.IncidentId);Add(command,"$severity",incident.Severity);Add(command,"$category",incident.Category);Add(command,"$account",incident.AccountId);Add(command,"$instance",incident.InstanceId);Add(command,"$occurred",incident.OccurredAtUtc.ToString("O"));Add(command,"$summary",incident.Summary);Add(command,"$evidence",incident.EvidenceJson);Add(command,"$hash",incident.ContentHash);await command.ExecuteNonQueryAsync(token);}
    public async Task<IReadOnlyList<GovernanceIncident>> GetIncidentsAsync(int limit=100,CancellationToken token=default){var list=new List<GovernanceIncident>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="SELECT IncidentId,Severity,Category,AccountId,InstanceId,OccurredAtUtc,Summary,EvidenceJson,ContentHash FROM GovernanceIncidents ORDER BY OccurredAtUtc DESC,rowid DESC LIMIT $limit";Add(command,"$limit",Math.Clamp(limit,1,500));await using var reader=await command.ExecuteReaderAsync(token);while(await reader.ReadAsync(token))list.Add(new(reader.GetString(0),reader.GetString(1),reader.GetString(2),reader.IsDBNull(3)?null:reader.GetString(3),reader.IsDBNull(4)?null:reader.GetString(4),DateTime.Parse(reader.GetString(5),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),reader.GetString(6),reader.GetString(7),reader.GetString(8)));return list;}
    private async Task InsertImmutableAsync(string table,string predicate,string hash,string json,string insert,IReadOnlyList<(string Name,object? Value)> parameters,CancellationToken token){await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using(var check=connection.CreateCommand()){check.CommandText=$"SELECT ContentHash FROM {table} WHERE {predicate}";foreach(var p in parameters)if(predicate.Contains(p.Name,StringComparison.Ordinal))Add(check,p.Name,p.Value);var scalar=await check.ExecuteScalarAsync(token);if(scalar is not null&&Convert.ToString(scalar,CultureInfo.InvariantCulture)!=hash)throw new InvalidOperationException($"{table} records are immutable.");if(scalar is not null)return;}await using var command=connection.CreateCommand();command.CommandText=insert;foreach(var p in parameters)Add(command,p.Name,p.Value);Add(command,"$hash",hash);Add(command,"$json",json);await command.ExecuteNonQueryAsync(token);}
    private async Task AppendEventAsync(string table,string subjectId,string type,DateTime occurred,string actor,string reason,object payload,CancellationToken token){var json=JsonSerializer.Serialize(payload,payload.GetType());var hash=GovernanceHash.Of(json);var eventId=$"GVE-{GovernanceHash.Of($"{table}|{subjectId}|{type}|{occurred:O}|{hash}")[..32]}";var subjectColumn=table=="GovernanceApprovalEvents"?"ApprovalId":"SuspensionId";await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText=$"INSERT OR IGNORE INTO {table}(EventId,{subjectColumn},EventType,OccurredAtUtc,Actor,Reason,PayloadJson,ContentHash) VALUES($event,$subject,$type,$occurred,$actor,$reason,$json,$hash)";Add(command,"$event",eventId);Add(command,"$subject",subjectId);Add(command,"$type",type);Add(command,"$occurred",occurred.ToString("O"));Add(command,"$actor",actor);Add(command,"$reason",reason);Add(command,"$json",json);Add(command,"$hash",hash);await command.ExecuteNonQueryAsync(token);}
    private async Task<IReadOnlyList<(string SubjectId,string Type,string Json)>> ReadEventsAsync(string table,string subjectColumn,CancellationToken token){var list=new List<(string,string,string)>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText=$"SELECT {subjectColumn},EventType,PayloadJson FROM {table} ORDER BY OccurredAtUtc,rowid";await using var reader=await command.ExecuteReaderAsync(token);while(await reader.ReadAsync(token))list.Add((reader.GetString(0),reader.GetString(1),reader.GetString(2)));return list;}
    private static T? Deserialize<T>(object? scalar)=>scalar is null or DBNull?default:JsonSerializer.Deserialize<T>(Convert.ToString(scalar,CultureInfo.InvariantCulture)!);private static void Add(SqliteCommand command,string name,object? value)=>command.Parameters.AddWithValue(name,value??DBNull.Value);
}
